#define PI 3.14159265359
#define TWO_PI 6.28318530718

float sparkle(float x, float y, float time) {
    return sin(x * 10.0 + time * 10.0) * sin(y * 100.0 + time * 12.0) * 0.5 + 0.5;
}
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453);
}


// Simple Perlin noise approximation
float perlinNoise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0,0.0)),
                   hash(i + vec2(1.0,0.0)), u.x),
               mix(hash(i + vec2(0.0,1.0)),
                   hash(i + vec2(1.0,1.0)), u.x), u.y);
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float time = iTime * 1.25;
    vec3 color = vec3(0.0);

    float scale = 0.8;
    const int NUM_PARTICLES = 70;

    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float seed = float(i) * 123.456;
        float particleTime = fract(time + id);

        vec2 particlePos;
        vec3 baseColor;

        if (fract(sin(seed) * 43758.5453123) < perlinNoise(vec2(seed, time))) {
           float startX = 0.14 * cos(id * TWO_PI + particleTime * 4.0) + 0.4 * perlinNoise(vec2(seed, time));
            float startY = -1.30999;
            float ySpeed = 0.7 + 0.9 * sin(id * PI + time);
            float yOffset = particleTime * ySpeed;
            particlePos = vec2(startX, startY + yOffset) * scale;


            baseColor = mix(vec3(0.1, 0.3, 0.9), vec3(1.0, 0.5, 0.0), id);
        } else {
            float startX = 0.08 * sin(id * TWO_PI + particleTime * 5.0) + .3 * perlinNoise(vec2(id, time));
            float startY = -1.3;
            float ySpeed = 0.9 + 0.5 * ((cos(id * PI + time)+0.5));
            float yOffset = particleTime * ySpeed;
            particlePos = vec2(startX, startY + yOffset) * scale;


            baseColor = mix(vec3(0.1, 0.3, 0.9), vec3(1.0, 0.5, 0.0), id);
        }

        float dist = length(uv - particlePos);
                float viscosity = exp(-pow(dist,1.930) * (pow((pow(uv.y+1.5,2.)),2.6)*220.00 +90.0 * (1.3 + particlePos.y + perlinNoise(vec2(seed, time * 0.1)))));

        float glitter = 0.092 * sparkle(particlePos.x, particlePos.y, time);
        baseColor += glitter * vec3(0.09, 0.5, 1.0);

        float fade = smoothstep(0.70, 0.1, dist);
        baseColor *= fade;

        color += baseColor * viscosity;
    }

    fragColor = vec4(color, 1.0);

    float vignette = 1.0 - pow(length(uv), 2.0) * 0.17;
    fragColor.rgb *= vignette;

    float intensity = dot(color, vec3(0.2126, 0.7152, 0.0722));
    float bloom = smoothstep(0.7, 1.0, intensity) * 0.015;
    fragColor.rgb += bloom * vec3(0.1, 0.8, 1.0);
    fragColor.a = 1.0-fragColor.g/19.0;
}

